internal class GUPPriceEngineAttributeGroupObject
{
    GUPPricingRule pricingRule;
    GUPPricingAttributeGroup pricingAttributeGroup;

    // Data type = GUPPriceEngineConditionValueObject.
    // Already sorted by attribute priority from largest (most specific) to smallest (most general).
    List attributeConditionValueList;

    // Excluded customer (from CustTable) or products (from InventTable).
    Set exclusionIdSet;

}

Method.Source:
public void new (GUPPricingRule _pricingRule, GUPPricingAttributeGroup _pricingAttributeGroup)
{
    // Make a copy by the cursor.
    this.pricingRule = _pricingRule.data();
    this.pricingAttributeGroup = _pricingAttributeGroup.data();
}

public List parmAttributeConditionValueList(List _attributeConditionValueList = null)
{
    if(_attributeConditionValueList != null)
    {
        this.attributeConditionValueList = _attributeConditionValueList;
    }
    return this.attributeConditionValueList;
}

/// <summary>
/// Put all excluded records' id in a set.
/// For header it's CustTable.AccountNum, and for line it's InventTable.ItemId.
/// </summary>
/// <param name = "_Id">An unique string id from either header (customer) or line (product).</param>
public void addExcludedId(str _Id)
{
    if (exclusionIdSet == null)
    {
        exclusionIdSet = new Set(Types::String);
    }
    exclusionIdSet.add(_Id);
}

public boolean isExcluded(str _recId)
{
    return this.exclusionIdSet != null && this.exclusionIdSet.in(_recId);
}

public boolean hasSameStructure(GUPPriceEngineAttributeGroupObject _other)
{
    if (attributeConditionValueList.elements() != _other.parmAttributeConditionValueList().elements())
    {
        return false;
    }

    // Two lists ensured to have same length now. Compare each attribute in sequence.
    ListEnumerator thisEnumerator = attributeConditionValueList.getEnumerator();
    ListEnumerator otherEnumerator = _other.parmAttributeConditionValueList().getEnumerator();

    while (thisEnumerator.moveNext())
    {
        GUPPriceEngineConditionValueObject thisConditionValue = thisEnumerator.current();

        otherEnumerator.moveNext();
        GUPPriceEngineConditionValueObject otherConditionValue = otherEnumerator.current();

        if (thisConditionValue.getAttributeKey() != otherConditionValue.getAttributeKey())
        {
            return false;
        }
    }
    return true;
}
